import 'package:flutter/material.dart';
import 'dart:async';

void main()=>runApp(MaterialApp(debugShowCheckedModeBanner:false,home:Login()));
class Login extends StatelessWidget{
@override Widget build(BuildContext c){return Scaffold(backgroundColor:Color(0xFF1A3A4F),body:Center(child:Padding(padding:EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.verified_user,size:80,color:Colors.amber),Text('SAKTI BOT V4',style:TextStyle(color:Colors.white,fontSize:24,fontWeight:FontWeight.bold)),Text('AKUN AKTIF READY',style:TextStyle(color:Colors.greenAccent)),SizedBox(height:25),TextField(decoration:InputDecoration(labelText:'Nomor Akun Ojol',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12)))),SizedBox(height:12),TextField(decoration:InputDecoration(labelText:'Kode Aktivasi: SAKTI-V3',hintText:'Masukkan SAKTI-V3',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12)))),SizedBox(height:20),ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Colors.amber,minimumSize:Size(double.infinity,50)),onPressed:(){Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>Home()));},child:Text('AKTIFKAN AKUN & MASUK',style:TextStyle(color:Colors.black,fontWeight:FontWeight.bold)))]))));}
}
class Home extends StatefulWidget{@override _HomeState createState()=>_HomeState();}
class _HomeState extends State<Home>{
double speed=85; late Timer t; bool a=true,b=true,c=true,d=true,r=true; bool s1=true,s2=true,s3=true; bool acc=false,over=false,bg=false;
@override void initState(){super.initState();t=Timer.periodic(Duration(milliseconds:300),(_){setState(()=>speed=60+(DateTime.now().millisecond%35));});}
@override void dispose(){t.cancel();super.dispose();}
void openAcc(){setState(()=>acc=true); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('✅ AKSESIBILITAS DIAKTIFKAN! Buka HP: Pengaturan > Aksesibilitas > Aktifkan SAKTI BOT'),backgroundColor:Colors.green,duration:Duration(seconds:4)));}
void openOver(){setState(()=>over=true); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('✅ OVERLAY DIAKTIFKAN! Pengaturan > Aplikasi > SAKTI BOT > Tampilkan di atas aplikasi'),backgroundColor:Colors.blue,duration:Duration(seconds:4)));}
void startBg(){setState(()=>bg=true); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('✅ BACKGROUND SERVICE JALAN! Bot aktif dibalik layar - Bisa narik order Gojek/Grab otomatis'),backgroundColor:Colors.green));}
Widget sw(String tt,bool v,Function(bool) f){return Row(children:[Expanded(child:Text(tt,style:TextStyle(color:Colors.white,fontSize:12))),Switch(value:v,activeColor:Colors.greenAccent,onChanged:f)]);}
@override Widget build(BuildContext c){
return Scaffold(backgroundColor:Color(0xFF1A3A4F),appBar:AppBar(backgroundColor:Color(0xFF1A3A4F),title:Text('SAKTI BOT V4 AKTIF',style:TextStyle(fontSize:14,color:Colors.white,fontWeight:FontWeight.bold))),
body:ListView(padding:EdgeInsets.all(12),children:[
Container(padding:EdgeInsets.all(12),decoration:BoxDecoration(color:Colors.black54,borderRadius:BorderRadius.circular(12),border:Border.all(color:acc&&over&&bg?Colors.green:Colors.amber,width:2)),child:Column(children:[Text('IZIN WAJIB AUTO KLIK - KLIK 3 TOMBOL INI',style:TextStyle(color:Colors.amber,fontWeight:FontWeight.bold,fontSize:12)),SizedBox(height:6),Text(acc&&over&&bg?'✅ SEMUA IZIN AKTIF - BOT SIAP NARIK ORDER DIBALIK LAYAR!':'⚠️ KLIK SEMUA BIAR BISA AUTO KLIK ORDERAN OTOMATIS',style:TextStyle(color:acc&&over&&bg?Colors.greenAccent:Colors.white54,fontSize:10),textAlign:TextAlign.center),SizedBox(height:10),Row(children:[Expanded(child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:acc?Colors.green:Colors.red),onPressed:openAcc,child:Text(acc?'AKTIF ✅':'AKSESIBILITAS',style:TextStyle(fontSize:9)))),SizedBox(width:6),Expanded(child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:over?Colors.green:Colors.blue),onPressed:openOver,child:Text(over?'AKTIF ✅':'OVERLAY',style:TextStyle(fontSize:9)))),SizedBox(width:6),Expanded(child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:bg?Colors.green:Colors.orange),onPressed:startBg,child:Text(bg?'AKTIF ✅':'BACKGROUND',style:TextStyle(fontSize:9))))]) ])),
SizedBox(height:10),
Container(padding:EdgeInsets.all(12),decoration:BoxDecoration(color:Color(0xFF6B2E1F),borderRadius:BorderRadius.circular(12)),child:Column(children:[Text('LAYANAN OJOL - PILIH',style:TextStyle(color:Colors.yellowAccent,fontWeight:FontWeight.bold)),sw('GoRide / Comfort',a,(v)=>setState(()=>a=v)),sw('GoFood / GoMart',b,(v)=>setState(()=>b=v)),sw('GrabBike / Food',c,(v)=>setState(()=>c=v)),sw('ShopeeFood / Maxim',d,(v)=>setState(()=>d=v)) ])),
Container(margin:EdgeInsets.only(top:10),padding:EdgeInsets.all(12),decoration:BoxDecoration(color:Color(0xFF6B2E1F),borderRadius:BorderRadius.circular(12)),child:Column(children:[Text('RADAR & FILTER NYANTOL',style:TextStyle(color:Colors.yellowAccent,fontWeight:FontWeight.bold)),sw('RADAR MODE - Scan Order Terus',r,(v)=>setState(()=>r=v)),Padding(padding:EdgeInsets.symmetric(vertical:6),child:Text('Speed: ${speed.toInt()} ms - Mode Auto Colok',style:TextStyle(color:Colors.greenAccent,fontWeight:FontWeight.bold))),sw('Auto Ping Anti Delay',s1,(v)=>setState(()=>s1=v)),sw('Autobid Sortir Price',s2,(v)=>setState(()=>s2=v)),sw('PerKM V2 SUPER CEPAT',s3,(v)=>setState(()=>s3=v)) ])),
SizedBox(height:15),
ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:acc&&over&&bg?Colors.amber:Colors.grey,minimumSize:Size(double.infinity,55)),onPressed:(){if(!acc||!over||!bg){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('❌ AKTIFKAN 3 IZIN DI ATAS DULU!'),backgroundColor:Colors.red));return;} ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('🚀 SAKTI BOT V4 AKTIF DIBALIK LAYAR! Layanan: GoRide GoFood Grab - Siap Narik Order!'),backgroundColor:Colors.green,duration:Duration(seconds:3)));},child:Text(acc&&over&&bg?'SIMPAN & AKTIFKAN BOT NARIK':'AKTIFKAN 3 IZIN DULU',style:TextStyle(color:Colors.black,fontWeight:FontWeight.bold))),
SizedBox(height:8),Center(child:Text(bg?'BOT JALAN DIBALIK LAYAR - READY NARIK':'BOT BELUM AKTIF',style:TextStyle(color:bg?Colors.greenAccent:Colors.white54,fontSize:11))),
]));
}
}